<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Template\Domain;

use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Holder\TemplateUidAttributeHolder;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Holder\TemplateCodeAttributeHolder;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Holder\TemplateTenantAttributeHolder;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Holder\TemplateThemeAttributeHolder;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Holder\TemplateChannelAttributeHolder;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Holder\TemplateEnabledAttributeHolder;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Holder\TemplateVersionAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;

class TemplateAttributes
{
    use TemplateUidAttributeHolder;
    use TemplateCodeAttributeHolder;
    use TemplateTenantAttributeHolder;
    use TemplateThemeAttributeHolder;
    use TemplateChannelAttributeHolder;
    use TemplateEnabledAttributeHolder;
    use TemplateVersionAttributeHolder;

    private const array UNSETS = [
      'uid' => 'unsetUid',
      'code' => 'unsetCode',
      'tenant' => 'unsetTenant',
      'theme' => 'unsetTheme',
      'channel' => 'unsetChannel',
      'enabled' => 'unsetEnabled',
      'version' => 'unsetVersion',
    ];

    public function createNewInstance(): Template
    {
        $errors = new ConstraintFailList();
        $uid = $this->uidTryBuildInitial($errors);
        $code = $this->codeTryBuildInitial($errors);
        $tenant = $this->tenantTryBuildInitial($errors);
        $theme = $this->themeTryBuildInitial($errors);
        $channel = $this->channelTryBuildInitial($errors);
        $enabled = $this->enabledTryBuildInitial($errors);
        $version = $this->versionTryBuildInitial($errors);
        if ($errors->hasErrors()) {
            throw $errors->asConstraintException();
        }
        \assert($uid !== null);
        \assert($code !== null);
        \assert($channel !== null);
        return new Template(
            uid: $uid,
            code: $code,
            tenant: $tenant,
            theme: $theme,
            channel: $channel,
            enabled: $enabled,
            version: $version,
        );
    }
    public function withAssertedRules(): TemplateAttributes
    {
        $value = new TemplateAttributes();
        $errorsList = new ConstraintFailList();
        $this->withAssertedUidRules($value, $errorsList);
        $this->withAssertedCodeRules($value, $errorsList);
        $this->withAssertedTenantRules($value, $errorsList);
        $this->withAssertedThemeRules($value, $errorsList);
        $this->withAssertedChannelRules($value, $errorsList);
        $this->withAssertedEnabledRules($value, $errorsList);
        $this->withAssertedVersionRules($value, $errorsList);
        if ($errorsList->hasErrors()) {
            throw $errorsList->asConstraintException();
        }
        return $value;
    }
    public function unset(string $field): void
    {
        if (isset(self::UNSETS[$field])) {
            call_user_func([$this, self::UNSETS[$field]]);
        }
    }
    public function withDefaults(): TemplateAttributes
    {
        $this->withDefaultUid();
        $this->withDefaultCode();
        $this->withDefaultTenant();
        $this->withDefaultTheme();
        $this->withDefaultChannel();
        $this->withDefaultEnabled();
        $this->withDefaultVersion();
        return $this;
    }
}
